args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?person (COALESCE(?b1, ?b2) AS ?birth) (COALESCE(?d1, ?d2) AS ?death) ((year(COALESCE(?d1, ?d2)) - year(COALESCE(?b1, ?b2))) AS ?years) WHERE {
  VALUES ?person { dbr:Ludovico_Sabbatini dbr:Marcelino_Manuel_da_Graça }
  OPTIONAL { ?person dbo:birthDate ?b1. }
  OPTIONAL { ?person dbp:birthDate ?b2. }
  OPTIONAL { ?person dbo:deathDate ?d1. }
  OPTIONAL { ?person dbp:deathDate ?d2. }
  FILTER(bound(COALESCE(?b1, ?b2)) && bound(COALESCE(?d1, ?d2)))
}
ORDER BY DESC(?years)
LIMIT 1

